        ...previous,
        lastMessageAt: now,
        lastFinalAt: isFinal ? now : Number(previous.lastFinalAt || 0),
        endOfTranscriptAt: endOfTranscript ? now : Number(previous.endOfTranscriptAt || 0),
        messageCount: Number(previous.messageCount || 0) + 1
